__d(function(o,e,t,n,i,b,d){i.exports=[{id:"note-alphabet",title:"\u0411\u0443\u0440\u044f\u0442\u0441\u043a\u0438\u0439 \u0430\u043b\u0444\u0430\u0432\u0438\u0442",body:"\u0412 \u0431\u0443\u0440\u044f\u0442\u0441\u043a\u043e\u043c \u0430\u043b\u0444\u0430\u0432\u0438\u0442\u0435 36 \u0431\u0443\u043a\u0432. \u041e\u043d \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d \u043d\u0430 \u0440\u0443\u0441\u0441\u043a\u043e\u0439 \u0433\u0440\u0430\u0444\u0438\u043a\u0435: \u043e\u0431\u0449\u0438\u0435 \u0441 \u0440\u0443\u0441\u0441\u043a\u0438\u043c \u0437\u0432\u0443\u043a\u0438 \u043f\u0438\u0448\u0443\u0442\u0441\u044f \u0442\u0435\u043c\u0438 \u0436\u0435 \u0431\u0443\u043a\u0432\u0430\u043c\u0438. \u0414\u043b\u044f \u043e\u0441\u043e\u0431\u044b\u0445 \u0437\u0432\u0443\u043a\u043e\u0432 \u0434\u043e\u0431\u0430\u0432\u043b\u0435\u043d\u044b \u0442\u0440\u0438 \u0431\u0443\u043a\u0432\u044b: \u04ae, \u04e8 (\u043f\u0438\u0448\u0435\u0442\u0441\u044f \u0443\u0434\u0432\u043e\u0435\u043d\u043d\u043e\u0439 \u2014 \u04e9\u04e9) \u0438 \u04ba.\n\n\u0411\u0443\u043a\u0432\u044b \u0432, \u043a, \u0444, \u0446, \u0447, \u0448, \u0449, \u044a \u0432\u0441\u0442\u0440\u0435\u0447\u0430\u044e\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u0437\u0430\u0438\u043c\u0441\u0442\u0432\u043e\u0432\u0430\u043d\u0438\u044f\u0445 \u0438\u0437 \u0440\u0443\u0441\u0441\u043a\u043e\u0433\u043e (\u0438 \u0446, \u0447 \u2014 \u0432 \u0438\u043c\u0435\u043d\u0430\u0445 \u0442\u0438\u0431\u0435\u0442\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u0438\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u044f).",source:{book:"bxr-textbook",page:1,section:"\xa72 \u0410\u043b\u0444\u0430\u0432\u0438\u0442"},verified:!1},{id:"note-special-sounds",title:"\u041e\u0441\u043e\u0431\u044b\u0435 \u0437\u0432\u0443\u043a\u0438: \u04bb, \u04af, \u04e9\u04e9",body:"\u04ba \u2014 \u0433\u043b\u0443\u0431\u043e\u043a\u0438\u0439 \u0449\u0435\u043b\u0435\u0432\u043e\u0439 \u0437\u0432\u0443\u043a, \u043e\u0431\u0440\u0430\u0437\u0443\u0435\u0442\u0441\u044f \u043c\u0435\u0436\u0434\u0443 \u043a\u043e\u0440\u043d\u0435\u043c \u044f\u0437\u044b\u043a\u0430 \u0438 \u0437\u0430\u0434\u043d\u0435\u0439 \u0441\u0442\u0435\u043d\u043a\u043e\u0439 \u0437\u0435\u0432\u0430. \u0412 \u043d\u0430\u0447\u0430\u043b\u0435 \u0441\u043b\u043e\u0432\u0430 \u0433\u043b\u0443\u0445\u043e\u0439 (\u04bb\u0430\u0439\u043d \u2014 \u0445\u043e\u0440\u043e\u0448\u0438\u0439, \u04bb\u0430\u043b\u0445\u0438\u043d \u2014 \u0432\u0435\u0442\u0435\u0440), \u0432 \u0441\u0435\u0440\u0435\u0434\u0438\u043d\u0435 \u0437\u0432\u043e\u043d\u043a\u0438\u0439 (\u0443\u04bb\u0430\u043d \u2014 \u0432\u043e\u0434\u0430). \u0417\u0432\u043e\u043d\u043a\u0438\u0439 \u043e\u0442\u0442\u0435\u043d\u043e\u043a \u0431\u043b\u0438\u0437\u043e\u043a \u043a \u0443\u043a\u0440\u0430\u0438\u043d\u0441\u043a\u043e\u043c\u0443 \xab\u0433\xbb.\n\n\u04ae \u2014 \u0443\u0437\u043a\u0438\u0439 \u043e\u0433\u0443\u0431\u043b\u0435\u043d\u043d\u044b\u0439 \u0433\u043b\u0430\u0441\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0434\u043d\u0435\u0433\u043e \u0440\u044f\u0434\u0430, \u0431\u043b\u0438\u0437\u043e\u043a \u043a \u0440\u0443\u0441\u0441\u043a\u043e\u043c\u0443 \xab\u0443\xbb \u0432 \u0441\u043b\u043e\u0432\u0430\u0445 \xab\u043f\u0443\u043b\u044f\xbb, \xab\u043b\u0443\u043d\u0430\xbb: \u0445\u04af\u0431\u04af\u04af\u043d \u2014 \u043c\u0430\u043b\u044c\u0447\u0438\u043a, \u04af\u043d\u044d\u043d \u2014 \u043f\u0440\u0430\u0432\u0434\u0430.\n\n\u04e8\u04e9 \u2014 \u0448\u0438\u0440\u043e\u043a\u0438\u0439 \u043e\u0433\u0443\u0431\u043b\u0435\u043d\u043d\u044b\u0439 \u0433\u043b\u0430\u0441\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0434\u043d\u0435\u0433\u043e \u0440\u044f\u0434\u0430, \u0432\u0441\u0435\u0433\u0434\u0430 \u0434\u043e\u043b\u0433\u0438\u0439: \u04e9\u04e9\u0445\u044d\u043d \u2014 \u0436\u0438\u0440, \u0441\u0430\u043b\u043e; \u04e9\u04e9\u0440\u04e9\u04e9 \u2014 \u0441\u0430\u043c. \u0411\u043b\u0438\u0436\u0435 \u0432\u0441\u0435\u0433\u043e \u043a \u0440\u0443\u0441\u0441\u043a\u043e\u043c\u0443 \xab\u043e\xbb.\n\n\u0423 \u2014 \u0443\u0437\u043a\u0438\u0439 \u043e\u0433\u0443\u0431\u043b\u0435\u043d\u043d\u044b\u0439 \u0433\u043b\u0430\u0441\u043d\u044b\u0439 \u0437\u0430\u0434\u043d\u0435\u0433\u043e \u0440\u044f\u0434\u0430, \u043d\u0435\u0447\u0442\u043e \u0441\u0440\u0435\u0434\u043d\u0435\u0435 \u043c\u0435\u0436\u0434\u0443 \u0440\u0443\u0441\u0441\u043a\u0438\u043c\u0438 \xab\u043e\xbb \u0438 \xab\u0443\xbb: \u0443\u04bb\u0430\u043d \u2014 \u0432\u043e\u0434\u0430, \u0448\u0443\u0431\u0443\u0443\u043d \u2014 \u043f\u0442\u0438\u0446\u0430.",source:{book:"bxr-textbook",page:2,section:"\xa73; \u0443\u0440\u043e\u043a 1, \u0441\u0442\u0440. 9"},verified:!1},{id:"note-n",title:"\u0414\u0432\u0430 \u0437\u0432\u0443\u043a\u0430 \u043d",body:"\u0411\u0443\u043a\u0432\u0430 \u043d \u043f\u0435\u0440\u0435\u0434\u0430\u0451\u0442 \u0434\u0432\u0430 \u0437\u0432\u0443\u043a\u0430. \u041f\u0435\u0440\u0435\u0434\u043d\u0435\u044f\u0437\u044b\u0447\u043d\u044b\u0439 \u043d \u2014 \u043a\u0430\u043a \u0440\u0443\u0441\u0441\u043a\u043e\u0435: \u043d\u0443\u0433\u0430 \u2014 \u043b\u0443\u0433, \u043d\u043e\u043c \u2014 \u043a\u043d\u0438\u0433\u0430. \u0417\u0430\u0434\u043d\u0435\u044f\u0437\u044b\u0447\u043d\u044b\u0439 \u043d (\u043d\u0433) \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u0439 \u0431\u0443\u043a\u0432\u043e\u0439 \u043d\u0435 \u043f\u0438\u0448\u0435\u0442\u0441\u044f; \u043e\u043d \u0437\u0432\u0443\u0447\u0438\u0442 \u0432 \u043a\u043e\u043d\u0446\u0435 \u0441\u043b\u043e\u0432\u0430 \u0438 \u043f\u0435\u0440\u0435\u0434 \u0445, \u0433: \u0437\u043e\u043d \u2014 \u043d\u0430\u0440\u043e\u0434, \u0445\u043e\u043d\u0445\u043e \u2014 \u0437\u0432\u043e\u043d\u043e\u043a.\n\n\u0412 \u0443\u043f\u0440\u0430\u0436\u043d\u0435\u043d\u0438\u044f\u0445 \u0443\u0447\u0435\u0431\u043d\u0438\u043a\u0430 \u0437\u0430\u0434\u043d\u0435\u044f\u0437\u044b\u0447\u043d\u044b\u0439 \u043d \u043f\u043e\u043a\u0430\u0437\u0430\u043d \u043a\u0430\u043a \xab\u043d(\u0433)\xbb.",source:{book:"bxr-textbook",page:3,section:"\xa74; \u0443\u0440\u043e\u043a 1, \u0441\u0442\u0440. 10"},verified:!1},{id:"note-iotated",title:"\u0419\u043e\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0433\u043b\u0430\u0441\u043d\u044b\u0435",body:"\u0411\u0443\u043a\u0432\u044b \u044f, \u0435, \u044e, \u0451 \u043e\u0431\u043e\u0437\u043d\u0430\u0447\u0430\u044e\u0442 \u0434\u0432\u0430 \u0437\u0432\u0443\u043a\u0430: \u0439 + \u0430, \u0439 + \u044d, \u0439 + \u0443, \u0439 + \u043e. \u041f\u0440\u0438\u043c\u0435\u0440\u044b: \u044f\u04bb\u0430\u043d \u2014 \u043a\u043e\u0441\u0442\u044c, \u0435\u0445\u044d \u2014 \u0431\u043e\u043b\u044c\u0448\u043e\u0439, \u044e\u04bb\u044d \u2014 \u0434\u0435\u0432\u044f\u0442\u044c, \u0445\u043e\u0451\u0440 \u2014 \u0434\u0432\u0430.\n\n\u0414\u043e\u043b\u0433\u0438\u0435 \u0433\u043b\u0430\u0441\u043d\u044b\u0435 \u043f\u043e\u0441\u043b\u0435 \u043c\u044f\u0433\u043a\u0438\u0445 \u0441\u043e\u0433\u043b\u0430\u0441\u043d\u044b\u0445 \u043f\u0438\u0448\u0443\u0442\u0441\u044f \u043a\u0430\u043a \u044f\u0430, \u0451\u043e, \u0435\u044d, \u044e\u0443: \u0442\u0430\u0445\u044f\u0430 \u2014 \u043a\u0443\u0440\u0438\u0446\u0430, \u043e\u0440\u0451\u043e \u2014 \u0441\u043b\u043e\u0436\u043d\u044b\u0439, \u04af\u043d\u0435\u044d\u043d \u2014 \u043a\u043e\u0440\u043e\u0432\u0430, \u0445\u0430\u0440\u044e\u0443 \u2014 \u043e\u0442\u0432\u0435\u0442.",source:{book:"bxr-textbook",page:3,section:"\xa75, \xa78\u0431; \u0443\u0440\u043e\u043a 2, \u0441\u0442\u0440. 11\u201314"},verified:!1},{id:"note-short-long",title:"\u041a\u0440\u0430\u0442\u043a\u0438\u0435 \u0438 \u0434\u043e\u043b\u0433\u0438\u0435 \u0433\u043b\u0430\u0441\u043d\u044b\u0435",body:"\u0414\u043e\u043b\u0433\u043e\u0442\u0430 \u0433\u043b\u0430\u0441\u043d\u043e\u0433\u043e \u043c\u0435\u043d\u044f\u0435\u0442 \u0441\u043c\u044b\u0441\u043b \u0441\u043b\u043e\u0432\u0430. \u0414\u043e\u043b\u0433\u0438\u0439 \u0433\u043b\u0430\u0441\u043d\u044b\u0439 \u043f\u0438\u0448\u0435\u0442\u0441\u044f \u0443\u0434\u0432\u043e\u0435\u043d\u043d\u043e\u0439 \u0431\u0443\u043a\u0432\u043e\u0439: \u0430\u0430, \u043e\u043e, \u044d\u044d, \u0438\u0438, \u0443\u0443, \u04af\u04af, \u04e9\u04e9 (\u0438 \u0434\u043e\u043b\u0433\u0438\u0439 \u044b).\n\n\u041f\u0440\u0438\u043c\u0435\u0440\u044b \u0438\u0437 \u0443\u0447\u0435\u0431\u043d\u0438\u043a\u0430: \u0437\u0430\u043d \u2014 \u043d\u0440\u0430\u0432, \u0437\u0430\u0430\u043d \u2014 \u0441\u043b\u043e\u043d; \u0431\u043e\u0440\u043e \u2014 \u0441\u0435\u0440\u044b\u0439, \u0431\u043e\u0440\u043e\u043e \u2014 \u0434\u043e\u0436\u0434\u044c; \u04af\u043b\u044d\u043d \u2014 \u0433\u043e\u043b\u043e\u0434\u043d\u044b\u0439, \u04af\u04af\u043b\u044d\u043d \u2014 \u0442\u0443\u0447\u0438.\n\n\u0413\u043b\u0430\u0441\u043d\u044b\u0435 \u043f\u0435\u0440\u0432\u043e\u0433\u043e \u0441\u043b\u043e\u0433\u0430 \u043f\u0440\u043e\u0438\u0437\u043d\u043e\u0441\u044f\u0442\u0441\u044f \u044f\u0441\u043d\u043e \u0438 \u0440\u0430\u0437\u043b\u0438\u0447\u0430\u044e\u0442 \u0441\u043b\u043e\u0432\u0430 (\u0433\u044d\u0440 \u2014 \u0434\u043e\u043c, \u0433\u0430\u0440 \u2014 \u0440\u0443\u043a\u0430). \u0413\u043b\u0430\u0441\u043d\u044b\u0435 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0445 \u0441\u043b\u043e\u0433\u043e\u0432 \u0437\u0432\u0443\u0447\u0430\u0442 \u0431\u0435\u0433\u043b\u043e \u0438 \u043d\u0435\u044f\u0441\u043d\u043e.",source:{book:"bxr-textbook",page:3,section:"\xa77\u20138; \u0443\u0440\u043e\u043a 3, \u0441\u0442\u0440. 15\u201319"},verified:!1},{id:"note-diphthongs",title:"\u0414\u0438\u0444\u0442\u043e\u043d\u0433\u0438",body:"\u0414\u0438\u0444\u0442\u043e\u043d\u0433\u0438 \u0430\u0439, \u043e\u0439, \u0443\u0439, \u044d\u0439, \u04af\u0439 \u2014 \u0434\u0432\u0430 \u0433\u043b\u0430\u0441\u043d\u044b\u0445, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043f\u0440\u043e\u0438\u0437\u043d\u043e\u0441\u044f\u0442\u0441\u044f \u0441\u043b\u0438\u0442\u043d\u043e \u0432 \u043e\u0434\u043d\u043e\u043c \u0441\u043b\u043e\u0433\u0435. \u041f\u043e \u0434\u043e\u043b\u0433\u043e\u0442\u0435 \u043e\u043d\u0438 \u0440\u0430\u0432\u043d\u044b \u0434\u043e\u043b\u0433\u0438\u043c \u0433\u043b\u0430\u0441\u043d\u044b\u043c. \u041f\u0440\u0438\u043c\u0435\u0440\u044b: \u0430\u0439\u043c\u0430\u0433 \u2014 \u0440\u0430\u0439\u043e\u043d, \u043e\u0439\u0440\u043e \u2014 \u0431\u043b\u0438\u0437\u043a\u043e, \u0433\u0443\u0439\u0445\u0430 \u2014 \u043f\u0440\u043e\u0441\u0438\u0442\u044c, \u0442\u04af\u0439\u043c\u044d\u0440 \u2014 \u043f\u043e\u0436\u0430\u0440.\n\n\u0412 \u043a\u043e\u043d\u0446\u0435 \u0441\u043b\u043e\u0432\u0430 \u0432\u043c\u0435\u0441\u0442\u043e \u0443\u0439, \u04af\u0439, \u044d\u0439 \u043f\u0438\u0448\u0435\u0442\u0441\u044f \u0434\u043e\u043b\u0433\u0438\u0439 \u044b: \u0430\u0433\u044b \u2014 \u043f\u0435\u0449\u0435\u0440\u0430, \u0433\u04af\u043d\u0437\u044d\u0433\u044b \u2014 \u0433\u043b\u0443\u0431\u043e\u043a\u0438\u0439.",source:{book:"bxr-textbook",page:4,section:"\xa79; \u0443\u0440\u043e\u043a 4, \u0441\u0442\u0440. 19\u201322"},verified:!1},{id:"note-vowel-harmony",title:"\u0420\u044f\u0434\u044b \u0433\u043b\u0430\u0441\u043d\u044b\u0445 \u0438 \u0441\u0438\u043d\u0433\u0430\u0440\u043c\u043e\u043d\u0438\u0437\u043c",body:"\u0413\u043b\u0430\u0441\u043d\u044b\u0435 \u0434\u0435\u043b\u044f\u0442\u0441\u044f \u043d\u0430 \u0442\u0440\u0438 \u0440\u044f\u0434\u0430: \u0437\u0430\u0434\u043d\u0438\u0435 (\u044d\u0440\u044d) \u2014 \u0430, \u043e, \u0443 \u0438 \u0438\u0445 \u0434\u043e\u043b\u0433\u0438\u0435; \u043f\u0435\u0440\u0435\u0434\u043d\u0438\u0435 (\u044d\u043c\u044d) \u2014 \u044d, \u04af, \u04e9\u04e9 \u0438 \u0438\u0445 \u0434\u043e\u043b\u0433\u0438\u0435; \u043d\u0435\u0439\u0442\u0440\u0430\u043b\u044c\u043d\u044b\u0435 (\u044d\u0440\u0441\u044d) \u2014 \u0438, \u0438\u0438, \u044b.\n\n\u0417\u0430\u043a\u043e\u043d \u0441\u0438\u043d\u0433\u0430\u0440\u043c\u043e\u043d\u0438\u0437\u043c\u0430: \u0435\u0441\u043b\u0438 \u0432 \u043f\u0435\u0440\u0432\u043e\u043c \u0441\u043b\u043e\u0433\u0435 \u0433\u043b\u0430\u0441\u043d\u044b\u0439 \u0437\u0430\u0434\u043d\u0435\u0433\u043e \u0440\u044f\u0434\u0430, \u0442\u043e \u0438 \u0434\u0430\u043b\u044c\u0448\u0435 \u0432 \u0441\u043b\u043e\u0432\u0435 \u0441\u0442\u043e\u044f\u0442 \u0433\u043b\u0430\u0441\u043d\u044b\u0435 \u0437\u0430\u0434\u043d\u0435\u0433\u043e \u0440\u044f\u0434\u0430; \u0435\u0441\u043b\u0438 \u043f\u0435\u0440\u0435\u0434\u043d\u0435\u0433\u043e \u2014 \u0442\u043e \u043f\u0435\u0440\u0435\u0434\u043d\u0435\u0433\u043e. \u041d\u0435\u0439\u0442\u0440\u0430\u043b\u044c\u043d\u044b\u0435 \u0441\u043e\u0447\u0435\u0442\u0430\u044e\u0442\u0441\u044f \u0441 \u043e\u0431\u043e\u0438\u043c\u0438 \u0440\u044f\u0434\u0430\u043c\u0438.\n\n\u0412 \u0443\u0447\u0435\u0431\u043d\u0438\u043a\u0435 \u0431\u0443\u043a\u0432\u044b \u0435, \u0451, \u044e \u043e\u0442\u043d\u0435\u0441\u0435\u043d\u044b \u043a \u0440\u044f\u0434\u0430\u043c \u043f\u043e-\u0440\u0430\u0437\u043d\u043e\u043c\u0443 (\u0441\u0442\u0440. 5 \u0438 \u0441\u0442\u0440. 23), \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043f\u043e \u043d\u0438\u043c \u0440\u044f\u0434 \u0432 \u0443\u043f\u0440\u0430\u0436\u043d\u0435\u043d\u0438\u0438 \u043d\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442\u0441\u044f.",source:{book:"bxr-textbook",page:5,section:"\xa710\u201311; \u0443\u0440\u043e\u043a 5, \u0441\u0442\u0440. 23\u201325"},verified:!1}]},861,[]);
